    {
      "card_ids": ["C14"],
      "claim": "The most similar evidence molecule, an iodinated methoxybenzamide, showed brain uptake of 0.6-0.8 %ID/g in mice, demonstrating that lipophilic aromatic amides with methoxy substitution can achieve meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The lipophilic amide Org-25543 crossed the BBB with a free brain/plasma ratio of approximately 0.5 in mice, supporting that neutral, lipophilic amides can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DEHP, a very lipophilic neutral ester, was detected in mouse brain after systemic exposure, indicating that high-logD neutral compounds can access the CNS despite physicochemical extremes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A methoxybenzamide piperazine analogue showed low brain uptake that increased dramatically after ABC-transporter inhibition, providing a contradictory efflux-liability signal; however, the query lacks the basic piperazine moiety that drives much of this phenotype.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "SNC121, a lipophilic benzamide/piperidine, had very low brain radioactivity in vivo and was labeled an efflux substrate, representing a contradictory example of poor CNS access despite lipophilicity.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted pass: the query is a highly lipophilic, neutral diacylhydrazine with low TPSA and HBD, likely to achieve meaningful CNS access via passive diffusion; supportive evidence from lipophilic amide/ester penetrants outweighs contradictory efflux-substrate examples that rely on basic amine moieties absent in the query.",
  "evidence_gaps": [
    "No direct CNS measurements for diacylhydrazine analogues.",
    "All evidence molecules have low Morgan similarity (<0.26) to the query.",
    "No unbound brain/plasma, CSF, or transporter-inhibition data are available for the query.",
    "Efflux liability of the query is inferred from physicochemical priors, not experimentally confirmed."
  ],
